fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    
    for &c in s {
        if c.is_ascii_uppercase() {
            // Convert ASCII uppercase to lowercase by adding 32
            let lowercase_char = (c as u8 + 32) as char;
            result.push(lowercase_char);
        } else {
            result.push(c);
        }
    }
    
    result
}